/**
 * Extract a fresh auth token from the user's browser session.
 *
 * Strategy (in order):
 *   1. Launch Chrome (headless) with the existing persistent profile
 *   2. Intercept outgoing API requests to capture the Authorization header
 *   3. If nothing intercepted in 3s, navigate to /api/v0/users/current
 *      from within the page context (same-origin, so cookies apply)
 *   4. Verify token with /api/v0/users/current
 *   5. Print JSON to stdout and exit
 *
 * Outputs one JSON line to stdout:
 *   { "success": true,  "token": "...", "verifiedAs": "user@example.com" }
 *   { "success": false, "error": "reason", "code": "NOT_LOGGED_IN" }
 *
 * Exit codes:
 *   0 — success
 *   1 — failure (auth error, network, etc.)
 *   2 — not logged in (re-run with --headed to sign in)
 *
 * Usage:
 *   node scripts/extract-ai-token.mjs              # headless (default)
 *   node scripts/extract-ai-token.mjs --headed     # visible window (first-time login)
 *   node scripts/extract-ai-token.mjs --verify     # just verify current token
 *   node scripts/extract-ai-token.mjs --verbose    # debug logging to stderr
 *
 * NOTE: We never call process.exit() directly. Instead we set process.exitCode
 * and return from main(), letting Node drain libuv handles naturally.
 * This prevents the Windows UV_HANDLE_CLOSING assertion crash.
 */

// playwright is imported dynamically below (only when needed) to avoid
// Playwright's native module loading in --verify mode on Windows.
import { existsSync, mkdirSync, readFileSync } from "node:fs";
import { dirname, join }      from "node:path";
import { fileURLToPath }      from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
// ROOT is the *consumer's* project root, not the package install dir.
// When invoked via tokenManager.ts, the child is spawned with cwd=consumer.
// When run standalone (`npm run token:refresh` in this repo), process.cwd()
// is this repo's root — same effect. Either way, .env and .deepseek-research/
// land beside the consumer's package.json, never inside node_modules/.
const ROOT      = process.env.AI_PROVIDERS_CONSUMER_ROOT ?? process.cwd();
const RESEARCH  = join(ROOT, ".deepseek-research");
const PROFILE   = join(RESEARCH, "chrome-profile");

const flags    = new Set(process.argv.slice(2));
const HEADED   = flags.has("--headed");
const VERBOSE  = flags.has("--verbose");
const VERIFY   = flags.has("--verify");

const TARGET     = "https://chat.deepseek.com";
const TIMEOUT_MS = 45_000;

function log(...args) {
  if (VERBOSE) console.error("[extract-token]", ...args);
}

function out(payload) {
  console.log(JSON.stringify(payload));
}

// ── Main (returns exit code; never calls process.exit directly) ────────────

async function main() {

  // ── Quick verify-only mode ─────────────────────────────────────────────────
  if (VERIFY) {
    const envPath = join(ROOT, ".env");
    let token = null;
    try {
      const env = readFileSync(envPath, "utf8");
      const m = env.match(/^DEEPSEEK_USER_TOKEN=(.+)$/m);
      token = m?.[1]?.trim() || null;
    } catch {}

    if (!token) {
      out({ success: false, error: "DEEPSEEK_USER_TOKEN not set in .env", code: "NOT_CONFIGURED" });
      return 1;
    }

    const res = await fetch(`${TARGET}/api/v0/users/current`, {
      headers: { authorization: `Bearer ${token}`, "content-type": "application/json" },
    }).catch(() => null);

    if (res?.ok) {
      const body = await res.json().catch(() => ({}));
      const email = body?.data?.biz_data?.email ?? body?.data?.biz_data?.username ?? "verified";
      out({ success: true, token, verifiedAs: email, mode: "verify-only" });
      return 0;
    }

    out({ success: false, error: `Token invalid — HTTP ${res?.status ?? "network error"}`, code: "INVALID_TOKEN" });
    return 1;
  }

  // ── Full extraction ────────────────────────────────────────────────────────
  mkdirSync(RESEARCH, { recursive: true });
  mkdirSync(PROFILE,  { recursive: true });

  log(`Launching Chrome (${HEADED ? "headed" : "headless"})...`);
  log(`Profile: ${PROFILE}`);

  const { chromium } = await import("playwright");

  const ctx = await chromium.launchPersistentContext(PROFILE, {
    channel:   "chrome",
    headless:  !HEADED,
    viewport:  { width: 1366, height: 768 },
    locale:    "en-US",
    timezoneId: "Asia/Riyadh",
    args: [
      "--disable-blink-features=AutomationControlled",
      "--exclude-switches=enable-automation",
      "--no-first-run",
      "--no-default-browser-check",
    ],
    ignoreDefaultArgs: ["--enable-automation"],
  }).catch(err => {
    out({ success: false, error: `Chrome launch failed: ${err.message}`, code: "LAUNCH_FAILED" });
    return null;
  });

  if (!ctx) return 1;

  // Remove webdriver flag (belt + suspenders approach)
  await ctx.addInitScript(() => {
    Object.defineProperty(navigator, "webdriver", { get: () => undefined });
    Object.defineProperty(navigator, "languages",  { get: () => ["en-US", "en", "ar"] });
  });

  const page = await ctx.newPage();
  let capturedToken = null;

  // ── Strategy 1: Intercept outgoing requests ────────────────────────────────
  page.on("request", req => {
    if (capturedToken) return;
    const url = req.url();
    if (!url.includes("/api/v0/") || url.includes("/login") || url.includes("/register")) return;
    const auth = req.headers()["authorization"] ?? "";
    if (auth.startsWith("Bearer ")) {
      capturedToken = auth.slice(7);
      log(`Token captured via request interception (${url})`);
    }
  });

  // ── Navigate ───────────────────────────────────────────────────────────────
  log(`Navigating to ${TARGET}...`);
  try {
    await page.goto(TARGET, { waitUntil: "domcontentloaded", timeout: TIMEOUT_MS });
  } catch (err) {
    await ctx.close();
    out({ success: false, error: `Navigation failed: ${err.message}`, code: "NAVIGATION_FAILED" });
    return 1;
  }

  // ── Strategy 2: Trigger an API call from page context ────────────────
  // Give natural requests 3 seconds first, then trigger one ourselves.
  if (!capturedToken) {
    log("Waiting 3s for natural API requests...");
    await page.waitForTimeout(3000);
  }

  if (!capturedToken) {
    log("Triggering /api/v0/users/current from page context...");
    try {
      await page.evaluate(async () => {
        try {
          // Same-origin fetch — browser sends session cookies automatically.
          await fetch("/api/v0/users/current", { credentials: "include" });
        } catch {}
      });
    } catch (err) {
      // Execution context can be destroyed by a navigation mid-evaluate.
      log(`page.evaluate skipped (navigation in progress): ${err.message.split("\n")[0]}`);
    }
    await page.waitForTimeout(2000);
  }

  // ── Strategy 3: Read from localStorage ────────────────────────────────────
  // The DeepSeek web app stores its tokens wrapped — entries look like
  //   {"value":"<token>","__version":"0"}
  // and the wrapper exists even when not signed in (with value: null). We
  // must unwrap and reject null/short values, otherwise the literal string
  // `{"value":null,...}` gets sent as a Bearer token and the server's
  // anonymous endpoint happily returns 200 — producing a false "verified"
  // with no real identity.
  if (!capturedToken) {
    log("Checking localStorage...");
    try {
      capturedToken = await page.evaluate(() => {
        const keys = [
          "token", "auth_token", "userToken", "ds_token",
          "access_token", "authToken", "bearerToken", "apiToken",
        ];
        const looksLikeToken = (s) =>
          typeof s === "string" && s.length >= 20 && !s.startsWith("{") && !/\s/.test(s);
        const unwrap = (raw) => {
          if (!raw) return null;
          // Try the wrapped shape first.
          try {
            const j = JSON.parse(raw);
            if (j && typeof j === "object") {
              const v = j.value ?? j.token ?? j.accessToken ?? null;
              return looksLikeToken(v) ? v : null;
            }
          } catch { /* not JSON — fall through */ }
          return looksLikeToken(raw) ? raw : null;
        };
        for (const k of keys) {
          const v = unwrap(localStorage.getItem(k));
          if (v) return v;
        }
        for (const k of keys) {
          const v = unwrap(sessionStorage.getItem(k));
          if (v) return v;
        }
        return null;
      });
    } catch (err) {
      log(`localStorage check skipped: ${err.message.split("\n")[0]}`);
    }
    if (capturedToken) log("Token found in storage");
  }

  // ── Headed sign-in wait: poll until the user signs in (or times out) ──────
  // The previous flow closed Chrome ~5s after launch, so first-time users
  // never got the chance to type credentials. In --headed mode we now wait
  // up to 5 minutes for either: (a) an authenticated /api/v0/* request to
  // fly out (captured by the request listener), or (b) a real token to land
  // in localStorage. Either signal means sign-in succeeded.
  if (!capturedToken && HEADED) {
    log("Headed mode: waiting up to 5 minutes for sign-in (window will stay open)...");
    const deadline = Date.now() + 5 * 60_000;
    while (!capturedToken && Date.now() < deadline) {
      await page.waitForTimeout(2000);
      try {
        capturedToken = await page.evaluate(() => {
          const keys = [
            "token", "auth_token", "userToken", "ds_token",
            "access_token", "authToken", "bearerToken", "apiToken",
          ];
          const looksLikeToken = (s) =>
            typeof s === "string" && s.length >= 20 && !s.startsWith("{") && !/\s/.test(s);
          const unwrap = (raw) => {
            if (!raw) return null;
            try {
              const j = JSON.parse(raw);
              if (j && typeof j === "object") {
                const v = j.value ?? j.token ?? j.accessToken ?? null;
                return looksLikeToken(v) ? v : null;
              }
            } catch {}
            return looksLikeToken(raw) ? raw : null;
          };
          for (const k of keys) {
            const v = unwrap(localStorage.getItem(k));
            if (v) return v;
          }
          for (const k of keys) {
            const v = unwrap(sessionStorage.getItem(k));
            if (v) return v;
          }
          return null;
        });
      } catch { /* navigation can destroy execution context — just retry */ }
    }
    if (capturedToken) log("Sign-in detected, token captured.");
    else log("Timed out waiting for sign-in.");
  }

  // ── Check login state ──────────────────────────────────────────────────────
  if (!capturedToken) {
    let notLoggedIn = false;
    try {
      notLoggedIn = await page.evaluate(() => {
        const url = window.location.href;
        return url.includes("/login") || url.includes("/register") ||
               !!document.querySelector("[class*='login-form']") ||
               !!document.querySelector("[class*='LoginForm']");
      });
    } catch {}

    await ctx.close();

    if (notLoggedIn) {
      out({
        success: false,
        error: "Not logged in — run: node scripts/extract-ai-token.mjs --headed",
        code: "NOT_LOGGED_IN",
      });
      return 2;
    }

    if (HEADED) {
      out({
        success: false,
        error: "Headed mode: sign in to the browser window that opened, then re-run without --headed",
        code: "NOT_LOGGED_IN",
      });
      return 2;
    }

    // Headless failed — profile is likely empty (first time setup)
    out({
      success: false,
      error: "Page loaded but no API request was intercepted. Run first: node scripts/extract-ai-token.mjs --headed to log in and save the session.",
      code: "TOKEN_NOT_FOUND",
    });
    return 1;
  }

  // ── Verify token ───────────────────────────────────────────────────────────
  log("Verifying token via /api/v0/users/current...");
  let verifiedAs = null;
  try {
    const result = await page.evaluate(async (token) => {
      const res = await fetch("/api/v0/users/current", {
        headers: { authorization: `Bearer ${token}`, "content-type": "application/json" },
      });
      if (!res.ok) return { ok: false, status: res.status };
      const body = await res.json();
      const data = body?.data?.biz_data;
      return { ok: true, identity: data?.email ?? data?.name ?? data?.username ?? "verified" };
    }, capturedToken);

    if (result.ok) {
      // Reject the "anonymous OK" case: the server returns 200 with no
      // identifying fields when the Authorization header is malformed —
      // we mustn't treat that as a successful sign-in.
      const identity = result.identity;
      if (identity && identity !== "verified") {
        verifiedAs = identity;
        log(`Verified as: ${verifiedAs}`);
      } else {
        log("Verification 200 but no identity in response — treating as unverified.");
      }
    } else {
      log(`Verification returned HTTP ${result.status}`);
    }
  } catch (err) {
    log(`Verification error: ${err.message}`);
  }

  await ctx.close();

  if (!verifiedAs) {
    out({
      success: false,
      error: "Token captured but failed verification — may be invalid or expired",
      code: "VERIFY_FAILED",
      token: capturedToken, // Include anyway so caller can decide
    });
    return 1;
  }

  out({ success: true, token: capturedToken, verifiedAs });
  return 0;
}

// Set exit code and let Node drain libuv handles naturally.
// Calling process.exit() directly causes an assertion crash on Windows
// when undici (Node's built-in fetch) still has open connections.
process.exitCode = await main();
